// Renders public/social-card.png, the 1200x630 image Discord shows when the
// site link is pasted. Run with `npm run social-card` after changing the copy
// here, then deploy.
//
// The card is drawn from the site's own fonts in headless Chromium rather than
// generated by a model, so the type matches the product exactly.
import { readFileSync } from "node:fs";
import { chromium } from "@playwright/test";

const font = (name) =>
  `data:font/woff2;base64,${readFileSync(`public/fonts/${name}`).toString("base64")}`;

const html = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<style>
@font-face{font-family:Fraunces;src:url(${font("fraunces-latin-600.woff2")}) format("woff2");font-weight:600}
@font-face{font-family:"Public Sans";src:url(${font("public-sans-latin-400.woff2")}) format("woff2");font-weight:400}
@font-face{font-family:"Public Sans";src:url(${font("public-sans-latin-500.woff2")}) format("woff2");font-weight:500}
@font-face{font-family:"IBM Plex Mono";src:url(${font("ibm-plex-mono-latin-400.woff2")}) format("woff2");font-weight:400}
:root{
  --paper:#f4eee3;--raised:#fbf7ef;--ink:#17130f;--ink-soft:#4e453b;--muted:#75695b;
  --line:#d8ccba;--line-strong:#b9a992;--accent:#b8431f;
}
*{box-sizing:border-box}
html,body{margin:0;width:1200px;height:630px;background:var(--paper);color:var(--ink);font-family:"Public Sans",system-ui,sans-serif}
.canvas{position:relative;width:1200px;height:630px;padding:58px 72px;display:grid;grid-template-columns:1fr 372px;gap:60px;align-items:center}
.frame{position:absolute;inset:22px;border:1px solid var(--line);border-radius:8px;pointer-events:none}
.badge{display:inline-flex;align-items:center;gap:9px;margin:0 0 20px;padding:6px 13px;border:1px solid var(--line-strong);border-radius:999px;background:var(--raised);font-size:12px;letter-spacing:.09em;text-transform:uppercase;color:var(--ink-soft)}
.dot{width:7px;height:7px;border-radius:50%;background:var(--accent)}
.wordmark{margin:0 0 18px;font-family:Fraunces,Georgia,serif;font-size:34px;font-weight:600;letter-spacing:-.02em;line-height:1}
h1{margin:0 0 18px;font-family:Fraunces,Georgia,serif;font-size:57px;font-weight:600;line-height:1.02;letter-spacing:-.028em}
.lede{margin:0;max-width:37ch;font-size:21px;line-height:1.45;color:var(--ink-soft)}
.url{position:absolute;left:72px;bottom:52px;font-family:"IBM Plex Mono",monospace;font-size:15px;color:var(--muted)}
.specimen{background:var(--raised);border:1px solid var(--line-strong);border-left:3px solid var(--accent);border-radius:6px;padding:28px 30px 24px;box-shadow:0 18px 40px rgba(23,19,15,.07)}
.specimen-label{margin:0;font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.rule{width:44px;height:2px;background:var(--accent);margin:12px 0 20px}
.series{margin:0;font-family:Fraunces,Georgia,serif;font-size:27px;line-height:1.15}
.chapter{margin:2px 0 10px;font-family:Fraunces,Georgia,serif;font-size:96px;font-weight:600;line-height:.9;letter-spacing:-.045em;color:var(--accent)}
.copy{margin:0;font-size:16px;color:var(--ink-soft)}
.foot{display:flex;justify-content:space-between;gap:12px;margin-top:22px;padding-top:12px;border-top:1px solid var(--line);font-family:"IBM Plex Mono",monospace;font-size:12px;color:var(--muted)}
</style>
</head>
<body>
<div class="canvas">
  <div class="frame"></div>
  <div>
    <p class="badge"><span class="dot"></span>Free launch — first 100 accounts</p>
    <p class="wordmark">Chapter Ping</p>
    <h1>Chapter alerts that land in Discord</h1>
    <p class="lede">Track weebcentral series. Get pinged the moment a new chapter drops.</p>
  </div>
  <div class="specimen">
    <p class="specimen-label">Example alert</p>
    <div class="rule"></div>
    <p class="series">One Piece</p>
    <p class="chapter">1132</p>
    <p class="copy">A new chapter is out.</p>
    <div class="foot"><span>Discord</span><span>Today, 10:00</span></div>
  </div>
  <p class="url">chapterping.vercel.app</p>
</div>
</body>
</html>`;

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1200, height: 630 }, deviceScaleFactor: 1 });
await page.setContent(html, { waitUntil: "load" });
await page.evaluate(() => globalThis.document.fonts.ready);
await page.screenshot({ path: "public/social-card.png", type: "png" });
await browser.close();
console.log("wrote public/social-card.png (1200x630)");
